window.MUN_COMMITTEE_INTELLIGENCE={"General Assembly Plenary":{"type":"UN principal organ","mandate":"Main deliberative, policymaking and representative organ; all 193 Member States participate with one vote.","authority":"Charter-wide deliberative and budgetary functions; recommendations and decisions within Charter limits.","outputs":["resolutions","decisions","declarations","budgetary decisions","elections and appointments"],"debate":"General debate, thematic debate, list of speakers, negotiations, draft resolutions, amendments and recorded/adopted decisions.","strategy":"Track regional-group dynamics, sponsors/co-sponsors, operative language, voting thresholds and whether the matter is plenary or committee-referred.","cautions":"Do not treat GA resolutions as automatically binding on states unless a specific legal basis applies.","sources":["https://www.un.org/pga/81/general-assembly/","https://www.un.org/en/ga/about/ropga/index.shtml"]},"First Committee (DISEC)":{"type":"GA Main Committee","mandate":"Disarmament and International Security.","authority":"Considers disarmament, global security and related international-security questions and recommends draft resolutions to the Assembly.","outputs":["draft resolutions","decisions","reports"],"debate":"Weapons systems, non-proliferation, arms control, outer space security, emerging technologies, conventional weapons and security architecture.","strategy":"Map security interests, treaty status, verification, compliance, civilian harm, export controls, financing and implementation mechanisms.","cautions":"Separate legal obligations from political commitments; verify treaty membership before asserting obligations.","sources":["https://www.un.org/en/ga/maincommittees/","https://www.un.org/en/ga/first/"]},"Second Committee (ECOFIN)":{"type":"GA Main Committee","mandate":"Economic and Financial.","authority":"Economic growth, development, financing, trade/development questions, macroeconomic and sustainable-development issues within GA competence.","outputs":["draft resolutions","decisions","reports"],"debate":"Development finance, debt, trade, technology transfer, poverty, food/energy security, commodities and sustainable development.","strategy":"Test proposals for funding source, implementation capacity, distributional effects, conditionality and measurable outcomes.","cautions":"Do not invent funding commitments or imply that a GA resolution can compel institutions beyond its authority.","sources":["https://www.un.org/en/ga/maincommittees/","https://www.un.org/en/ga/second/"]},"Third Committee (SOCHUM)":{"type":"GA Main Committee","mandate":"Social, Humanitarian and Cultural.","authority":"Human rights, humanitarian and social issues referred to it by the Assembly.","outputs":["draft resolutions","decisions","reports"],"debate":"Human rights, refugees, migration, women, children, disability, discrimination, humanitarian protection and social development.","strategy":"Ground claims in treaties, UN mechanisms and documented evidence; separate normative commitments from enforcement mechanisms.","cautions":"Avoid claiming a treaty obligation without checking ratification/status; avoid treating allegations as established facts.","sources":["https://www.un.org/en/ga/maincommittees/","https://www.ohchr.org/en/countries"]},"Fourth Committee (SPECPOL)":{"type":"GA Main Committee","mandate":"Special Political and Decolonization.","authority":"Special political questions, decolonization and related agenda items assigned by the Assembly.","outputs":["draft resolutions","decisions","reports"],"debate":"Decolonization, peacekeeping-related political questions, information, special political situations and selected regional issues.","strategy":"Track mandate, status of territories, relevant resolutions and the exact language used in prior decisions.","cautions":"Do not collapse separate territorial, sovereignty and self-determination questions into one legal claim.","sources":["https://www.un.org/en/ga/maincommittees/","https://www.un.org/dppa/decolonization/en"]},"Fifth Committee":{"type":"GA Main Committee","mandate":"Administrative and Budgetary.","authority":"Administrative and budgetary matters of the United Nations.","outputs":["budget decisions","administrative decisions","reports","appropriation decisions"],"debate":"Programme budgets, assessments, peacekeeping financing, staffing, oversight, efficiency and resources.","strategy":"Every proposal should answer cost, funding source, mandate, implementation body, oversight and audit questions.","cautions":"Budget authority and assessed contributions are technical; do not invent percentages or funding mechanisms.","sources":["https://www.un.org/en/ga/maincommittees/","https://www.un.org/en/ga/fifth/"]},"Sixth Committee":{"type":"GA Main Committee","mandate":"Legal.","authority":"Legal matters referred by the General Assembly.","outputs":["draft resolutions","conventions","reports","legal recommendations"],"debate":"International law, treaty law, state responsibility, jurisdiction, terrorism-law questions, codification and legal development.","strategy":"Identify the legal question, applicable instrument, state consent, jurisdiction, precedent and implementation pathway.","cautions":"Distinguish treaty law, customary international law, Charter provisions, General Assembly recommendations and domestic law.","sources":["https://www.un.org/en/ga/maincommittees/","https://legal.un.org/"]},"Security Council":{"type":"UN principal organ","mandate":"Primary responsibility for international peace and security.","authority":"Under the Charter it can adopt decisions binding on Member States in applicable cases, impose sanctions and authorize measures including force under the Charter framework.","outputs":["resolutions","presidential statements","press statements","sanctions decisions","mandates"],"debate":"Crisis management, ceasefires, sanctions, peace operations, authorization, reporting, humanitarian access and conflict-specific diplomacy.","strategy":"Track P5 positions, elected members, veto exposure, draft language, operative authority and whether the text is politically or legally actionable.","cautions":"The Council has 15 members; P5 veto dynamics and voting requirements matter. Do not treat a simulated MUN voting rule as identical to the real Council unless the conference says so.","sources":["https://main.un.org/securitycouncil/en/content/current-members","https://main.un.org/securitycouncil/en/content/voting-system"]},"ECOSOC":{"type":"UN principal organ","mandate":"Coordinates economic, social and related work of the UN system.","authority":"Forum for discussion, coordination, policy recommendations and interaction with functional commissions and specialized agencies.","outputs":["resolutions","decisions","ministerial declarations","coordination outcomes"],"debate":"Development, financing, SDGs, economic policy, social issues and coordination across the UN development system.","strategy":"Connect proposals to SDGs, measurable indicators, financing, institutional responsibility and cross-agency coordination.","cautions":"Do not attribute operational powers of specialized agencies directly to ECOSOC.","sources":["https://ecosoc.un.org/"]},"Human Rights Council":{"type":"UN subsidiary intergovernmental body","mandate":"Promotes and protects human rights and addresses human-rights situations and thematic issues.","authority":"Intergovernmental deliberation, resolutions, recommendations, Universal Periodic Review and special procedures framework.","outputs":["resolutions","decisions","UPR outcomes","mandate renewals","recommendations"],"debate":"Country situations, thematic rights, accountability, treaty implementation, UPR and special procedures.","strategy":"Use primary UN/OHCHR documents; distinguish allegations, findings, recommendations and binding law.","cautions":"Council membership is regionally allocated and changes by election; check the current session before making membership claims.","sources":["https://www.ohchr.org/en/hr-bodies/hrc"]},"WHO":{"type":"UN specialized agency","mandate":"International public health.","authority":"World Health Assembly and WHO constitutional framework; technical standards, coordination and health emergencies within its mandate.","outputs":["resolutions","decisions","technical guidance","action plans"],"debate":"Pandemic preparedness, surveillance, vaccines, antimicrobial resistance, health systems, access and financing.","strategy":"Specify implementation agency, surveillance, procurement, financing, data-sharing and equity safeguards.","cautions":"Do not give WHO powers it does not possess; distinguish recommendations from binding instruments.","sources":["https://www.who.int/about/governance/world-health-assembly"]},"UNEP":{"type":"UN programme","mandate":"Global environmental authority and coordination.","authority":"Coordinates environmental work and supports environmental governance, science and policy.","outputs":["decisions","action plans","assessments","environmental initiatives"],"debate":"Climate, biodiversity, pollution, chemicals, waste, oceans and environmental governance.","strategy":"Specify targets, finance, technology transfer, measurement, reporting and national implementation.","cautions":"Separate UNEP's coordinating role from treaty bodies and UNFCCC institutions.","sources":["https://www.unep.org/who-we-are"]},"UN Women":{"type":"UN entity","mandate":"Gender equality and women's empowerment.","authority":"Supports normative, operational and coordination work on gender equality within the UN system.","outputs":["policy frameworks","programmes","reports","decisions through relevant governing bodies"],"debate":"Gender-based violence, political participation, economic empowerment, education, peace and security and institutional equality.","strategy":"Use measurable protections, survivor-centered implementation, financing, data and accountability.","cautions":"Do not attribute sovereign domestic-policy powers to UN Women.","sources":["https://www.unwomen.org/en/about-us"]},"UNHCR":{"type":"UN agency","mandate":"International protection of refugees and solutions to displacement.","authority":"Protection and assistance within its mandate, coordination and durable-solutions work.","outputs":["protection guidance","programmes","appeals","reports"],"debate":"Refugee protection, asylum, statelessness, displacement, resettlement and humanitarian response.","strategy":"Address legal status, registration, protection, host-state capacity, funding and durable solutions.","cautions":"Refugee, asylum-seeker, internally displaced person and migrant are not interchangeable categories.","sources":["https://www.unhcr.org/about-unhcr"]},"International Court of Justice (ICJ)":{"type":"UN principal judicial organ","mandate":"Settles legal disputes between states within its jurisdiction and gives advisory opinions.","authority":"Jurisdiction depends on state consent through applicable legal bases; judgments are between parties to a case.","outputs":["judgments","orders","advisory opinions"],"debate":"Jurisdiction, admissibility, merits, provisional measures, treaty interpretation and state responsibility.","strategy":"Identify jurisdictional hook before merits; separate factual allegations from legal elements and remedies.","cautions":"ICJ is not a criminal court and does not prosecute individuals.","sources":["https://www.icj-cij.org/court"]},"International Criminal Court (ICC)":{"type":"Independent international court","mandate":"Prosecutes individuals for genocide, crimes against humanity, war crimes and aggression within its jurisdiction.","authority":"Rome Statute jurisdiction and admissibility framework.","outputs":["prosecutor applications","decisions","warrants","judgments","orders"],"debate":"Jurisdiction, complementarity, evidence, command responsibility, victim protection and cooperation.","strategy":"Separate state responsibility from individual criminal responsibility and verify Rome Statute status.","cautions":"ICC is not a UN organ and its jurisdiction is not universal.","sources":["https://www.icc-cpi.int/about/the-court"]}};
